INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a5',1,'APPROVED','PUBLISHED',
'{"objectives":["Compare political systems at B2","Use politische Systeme vocabulary","Analyse democratic vs authoritarian models"],"explanation":{"intro":"Political systems vocabulary covers democracy, authoritarianism, and hybrid regimes at B2.","culturalNote":"Key political system types: Demokratie (liberal democracy), Autokratie (autocracy), Oligarchie (oligarchy), Theokratie (theocracy), Hybridregime (hybrid regime). Freedom House and V-Dem rank Germany consistently as a full democracy. The Grundgesetz was designed to prevent a return to authoritarianism — hence the streitbare Demokratie (militant democracy) concept."},"examples":[{"german":"Demokratische Systeme zeichnen sich durch freie Wahlen, Gewaltenteilung und den Schutz von Grundrechten aus.","english":"Democratic systems are characterised by free elections, separation of powers, and the protection of fundamental rights."},{"german":"Die Gewaltenteilung zwischen Legislative, Exekutive und Judikative ist ein Kernelement des Rechtsstaats.","english":"The separation of powers between legislature, executive, and judiciary is a core element of the constitutional state."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can compare political systems and discuss democratic principles at B2."}}',
'{"items":[{"word":"die Gewaltenteilung","translation":"separation of powers","pronunciation":"dee geh-VAL-ten-ty-loong","example":"Gewaltenteilung."},{"word":"die Legislative","translation":"legislature","pronunciation":"dee leh-gis-lah-TEE-veh","example":"Die Legislative."},{"word":"die Exekutive","translation":"executive","pronunciation":"dee ek-zeh-koo-TEE-veh","example":"Die Exekutive."},{"word":"die Judikative","translation":"judiciary","pronunciation":"dee yoo-dee-kah-TEE-veh","example":"Die Judikative."},{"word":"sich auszeichnen durch","translation":"to be characterised by/distinguished by","pronunciation":"zikh OWS-tsykh-nen doorhh","example":"Sich auszeichnen durch."},{"word":"das Kernelement","translation":"core element","pronunciation":"dahs KERN-eh-leh-ment","example":"Kernelement."}]}',
'{"title":"Sich auszeichnen durch — to be distinguished/characterised by","pattern":"sich auszeichnen durch + accusative = to be distinguished by, stand out through (positive characteristic)","explanation":"Sich auszeichnen durch + accusative = to be characterised by (positively), to stand out through. Demokratien zeichnen sich durch Wahlen aus = Democracies are distinguished by elections. Perfect: hat sich ausgezeichnet. Die Auszeichnung = distinction, award. Compare: geprägt von (characterised/shaped by — can be neutral or negative), sich abheben von (to stand out from — comparative).","examples":[{"sentence":"Das Produkt zeichnet sich durch hohe Qualität aus.","translation":"The product is distinguished by high quality."},{"sentence":"Sie zeichnet sich durch ihre Ausdauer aus.","translation":"She is distinguished by her perseverance."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gewaltenteilung'' means?","options":["separation of powers","division of violence","power division","governmental split"],"correctAnswer":"separation of powers"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Democratic systems are characterised by free elections, separation of powers, and the protection of fundamental rights.","options":["Demokratische Systeme zeichnen sich durch freie Wahlen, Gewaltenteilung und den Schutz von Grundrechten aus.","Demokratien haben freie Wahlen und Grundrechte.","Freiheit und Gewaltenteilung kennzeichnen Demokratien.","In Demokratien gibt es Wahlen und Grundrechte."],"correctAnswer":"Demokratische Systeme zeichnen sich durch freie Wahlen, Gewaltenteilung und den Schutz von Grundrechten aus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Produkt zeichnet sich durch hohe Qualität ___.","options":["aus","ab","an","ein"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She is distinguished by her perseverance","wordBankItems":["Sie","zeichnet","sich","durch","ihre","Ausdauer","aus","."],"correctAnswer":"Sie zeichnet sich durch ihre Ausdauer aus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Judikative'' means?","options":["judiciary","judge","justice","judicial branch"],"correctAnswer":"judiciary"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss democracy theory at B2","Use Demokratietheorie vocabulary","Talk about democratic legitimacy and participation"],"explanation":{"intro":"Democracy theory vocabulary covers legitimacy, participation, deliberation, and democratic challenges.","culturalNote":"Key democracy theories: deliberative Demokratie (Habermas — democracy as reasoned public discourse), partizipatorische Demokratie (participatory democracy — direct citizen involvement), Repräsentativdemokratie (representative democracy). German Wahlrecht (voting rights): Bundestagswahl uses a mixed-member proportional system (personalisiertes Verhältniswahlrecht)."},"examples":[{"german":"Demokratische Legitimität beruht auf der Zustimmung der Regierten und der Möglichkeit zur Abwahl.","english":"Democratic legitimacy rests on the consent of the governed and the possibility of voting out."},{"german":"Sinkende Wahlbeteiligung wird oft als Zeichen schwindenden Vertrauens in demokratische Institutionen interpretiert.","english":"Declining voter turnout is often interpreted as a sign of waning trust in democratic institutions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss democratic theory, legitimacy, and participation at B2."}}',
'{"items":[{"word":"die Legitimität","translation":"legitimacy","pronunciation":"dee leh-gee-tee-mee-TÄT","example":"Demokratische Legitimität."},{"word":"die Abwahl","translation":"voting out","pronunciation":"dee AP-vahl","example":"Möglichkeit zur Abwahl."},{"word":"schwindend","translation":"waning/dwindling","pronunciation":"SHVIN-dend","example":"Schwindendes Vertrauen."},{"word":"die Wahlbeteiligung","translation":"voter turnout","pronunciation":"dee VAHL-beh-ty-lee-goong","example":"Wahlbeteiligung."},{"word":"interpretieren","translation":"to interpret","pronunciation":"in-ter-preh-TEER-en","example":"Als Zeichen interpretieren."},{"word":"die Zustimmung","translation":"consent/approval","pronunciation":"dee TSOO-shtim-oong","example":"Zustimmung der Regierten."}]}',
'{"title":"Als ... interpretieren / interpretiert werden als — to interpret as","pattern":"etwas als + accusative interpretieren = to interpret something as (analytical framing)","explanation":"Interpretieren als + accusative = to interpret as. Etwas wird als Zeichen interpretiert = something is interpreted as a sign. Active: Man interpretiert X als Y. Passive: X wird als Y interpretiert. Common in academic and journalistic analysis. Synonyms: deuten als (to interpret as — slightly more literary), verstehen als (to understand as — more everyday), auffassen als (to take/construe as — formal).","examples":[{"sentence":"Sein Schweigen wurde als Zustimmung interpretiert.","translation":"His silence was interpreted as consent."},{"sentence":"Die Ergebnisse können als Hinweis auf einen Trend interpretiert werden.","translation":"The results can be interpreted as an indication of a trend."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abwahl'' means?","options":["voting out","voting away","removal by vote","electoral defeat"],"correctAnswer":"voting out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Declining voter turnout is often interpreted as a sign of waning trust in democratic institutions.","options":["Sinkende Wahlbeteiligung wird oft als Zeichen schwindenden Vertrauens in demokratische Institutionen interpretiert.","Weniger Wähler gehen wählen, weil sie den Institutionen nicht vertrauen.","Schwindendes Vertrauen führt zu niedrigerer Wahlbeteiligung.","Die Demokratie leidet unter sinkender Wahlbeteiligung."],"correctAnswer":"Sinkende Wahlbeteiligung wird oft als Zeichen schwindenden Vertrauens in demokratische Institutionen interpretiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sein Schweigen wurde als Zustimmung ___.","options":["interpretiert","interpretiert wurde","zu interpretieren","interpretierend"],"correctAnswer":"interpretiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The results can be interpreted as an indication of a trend","wordBankItems":["Die","Ergebnisse","können","als","Hinweis","auf","einen","Trend","interpretiert","werden","."],"correctAnswer":"Die Ergebnisse können als Hinweis auf einen Trend interpretiert werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Schwindend'' means?","options":["waning/dwindling","shrinking","disappearing","fading"],"correctAnswer":"waning/dwindling"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss populism at B2","Use Populismus vocabulary","Analyse populist rhetoric and its effects"],"explanation":{"intro":"Populism vocabulary covers the concept, its variants, and democratic challenges at B2.","culturalNote":"Populismus is a contested concept. Jan-Werner Müller''s definition: populists claim to represent the true people against a corrupt elite. Key features: Manichäismus (us vs. them), Volk vs. Establishment, Krisendiskurs (crisis narrative). In Germany: AfD (Alternative für Deutschland) is often called rechtspopulistisch. The concept Rechtspopulismus (right-wing populism) is widely used."},"examples":[{"german":"Populisten beanspruchen, das wahre Volk zu repräsentieren, und stellen alle anderen als illegitime Elite dar.","english":"Populists claim to represent the true people, and portray all others as an illegitimate elite."},{"german":"Populismus stellt eine Herausforderung für liberale Demokratien dar, da er komplexe Probleme vereinfacht und Feindbilder konstruiert.","english":"Populism poses a challenge to liberal democracies because it simplifies complex problems and constructs enemy images."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss populism, its features, and democratic challenges at B2."}}',
'{"items":[{"word":"beanspruchen","translation":"to claim/assert","pronunciation":"beh-AN-shprookh-en","example":"Zu beanspruchen."},{"word":"illegitim","translation":"illegitimate","pronunciation":"il-leh-gee-TEEM","example":"Illegitime Elite."},{"word":"darstellen als","translation":"to portray/present as","pronunciation":"DAR-shtel-en als","example":"Als Elite darstellen."},{"word":"das Feindbild","translation":"enemy image","pronunciation":"dahs FYNT-bilt","example":"Feindbilder konstruieren."},{"word":"vereinfachen","translation":"to simplify","pronunciation":"fer-YN-fakh-en","example":"Probleme vereinfachen."},{"word":"konstruieren","translation":"to construct","pronunciation":"kon-stroo-EER-en","example":"Feindbilder konstruieren."}]}',
'{"title":"Darstellen als — to portray/present as","pattern":"jemanden/etwas als + accusative darstellen = to portray, present, depict as","explanation":"Darstellen als + accusative = to portray as, present as, depict as. Er stellt sie als Feinde dar = He portrays them as enemies. Perfect: hat dargestellt. Die Darstellung = portrayal, depiction, representation. Compare: bezeichnen als (to describe/label as — factual or labelling), beschreiben als (to describe as — descriptive), brandmarken als (to brand/stigmatise as — negative).","examples":[{"sentence":"Die Medien stellten ihn als Helden dar.","translation":"The media portrayed him as a hero."},{"sentence":"Das Unternehmen stellte den Rückgang als vorübergehend dar.","translation":"The company portrayed the decline as temporary."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Beanspruchen'' means?","options":["to claim/assert","to demand","to require","to take up"],"correctAnswer":"to claim/assert"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Populists claim to represent the true people, and portray all others as an illegitimate elite.","options":["Populisten beanspruchen, das wahre Volk zu repräsentieren, und stellen alle anderen als illegitime Elite dar.","Populisten sagen, sie vertreten das Volk gegen die Elite.","Populisten gegen die Elite ist das Kernthema.","Populisten behaupten, das wahre Volk zu vertreten."],"correctAnswer":"Populisten beanspruchen, das wahre Volk zu repräsentieren, und stellen alle anderen als illegitime Elite dar."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Medien stellten ihn als Helden ___.","options":["dar","heraus","vor","ab"],"correctAnswer":"dar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The company portrayed the decline as temporary","wordBankItems":["Das","Unternehmen","stellte","den","Rückgang","als","vorübergehend","dar","."],"correctAnswer":"Das Unternehmen stellte den Rückgang als vorübergehend dar ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vereinfachen'' means?","options":["to simplify","to make easier","to reduce","to streamline"],"correctAnswer":"to simplify"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss civil society at B2","Use Zivilgesellschaft vocabulary","Talk about NGOs and civic engagement"],"explanation":{"intro":"Civil society vocabulary covers NGOs, volunteering, civic engagement, and social movements at B2.","culturalNote":"Deutschland hat eine starke Zivilgesellschaft: 600,000+ Vereine (associations), 30 million volunteers (Ehrenamtliche), strong unions (Gewerkschaften — DGB), churches, and NGOs. Wohlfahrtsverbände (welfare organisations — Caritas, Diakonie, AWO) run social services. The concept soziales Kapital (social capital) captures the value of civic networks."},"examples":[{"german":"Eine lebendige Zivilgesellschaft stärkt die Demokratie, indem sie staatliches Handeln kontrolliert und bürgerliche Interessen artikuliert.","english":"A vibrant civil society strengthens democracy by monitoring state action and articulating civic interests."},{"german":"Ehrenamtliches Engagement ist der Kitt, der gesellschaftlichen Zusammenhalt möglich macht.","english":"Voluntary engagement is the glue that makes social cohesion possible."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss civil society, volunteering, and civic engagement at B2."}}',
'{"items":[{"word":"lebendig","translation":"vibrant/lively","pronunciation":"leh-BEN-dikh","example":"Lebendige Zivilgesellschaft."},{"word":"der Kitt","translation":"glue/cement (figurative)","pronunciation":"dayr kit","example":"Der Kitt der Gesellschaft."},{"word":"der Zusammenhalt","translation":"cohesion/solidarity","pronunciation":"dayr tsoo-ZAM-en-halt","example":"Gesellschaftlicher Zusammenhalt."},{"word":"ehrenamtlich","translation":"voluntary/voluntary work","pronunciation":"EH-ren-amt-likh","example":"Ehrenamtlich tätig sein."},{"word":"artikulieren","translation":"to articulate/express","pronunciation":"ar-tee-koo-LEER-en","example":"Interessen artikulieren."},{"word":"kontrollieren","translation":"to monitor/control","pronunciation":"kon-tro-LEER-en","example":"Staatliches Handeln kontrollieren."}]}',
'{"title":"Indem — by doing (simultaneous means)","pattern":"indem + V-final clause = by doing, through doing (describes the means by which something is achieved)","explanation":"Indem = by (doing), through (doing). Expresses the means simultaneously: Sie stärkt die Demokratie, indem sie kontrolliert = It strengthens democracy by monitoring. Key: both actions happen at the same time, one is the means of the other. Compare: dadurch, dass (by the fact that — slightly more formal), durch + Nominalisierung (by + gerund noun: durch Kontrolle = by monitoring — more formal written alternative). Indem-clause = subordinate (V-final).","examples":[{"sentence":"Er lernte Deutsch, indem er täglich podcasts hörte.","translation":"He learnt German by listening to podcasts daily."},{"sentence":"Man spart Energie, indem man Geräte ausschaltet.","translation":"One saves energy by switching off devices."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Zusammenhalt'' means?","options":["cohesion/solidarity","togetherness","unity","collective strength"],"correctAnswer":"cohesion/solidarity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A vibrant civil society strengthens democracy by monitoring state action and articulating civic interests.","options":["Eine lebendige Zivilgesellschaft stärkt die Demokratie, indem sie staatliches Handeln kontrolliert und bürgerliche Interessen artikuliert.","Die Zivilgesellschaft ist wichtig für die Demokratie.","Durch Kontrolle und Artikulation stärkt die Zivilgesellschaft die Demokratie.","Zivilgesellschaft stärkt Demokratie."],"correctAnswer":"Eine lebendige Zivilgesellschaft stärkt die Demokratie, indem sie staatliches Handeln kontrolliert und bürgerliche Interessen artikuliert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er lernte Deutsch, indem er täglich Podcasts ___.","options":["hörte","gehört hat","hören würde","hören"],"correctAnswer":"hörte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: One saves energy by switching off devices","wordBankItems":["Man","spart","Energie",",","indem","man","Geräte","ausschaltet","."],"correctAnswer":"Man spart Energie , indem man Geräte ausschaltet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ehrenamtlich'' means?","options":["voluntary/honorary","honorary","unpaid","civic"],"correctAnswer":"voluntary/honorary"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001a9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss protest and activism at B2","Use Protest vocabulary","Talk about social movements"],"explanation":{"intro":"Protest and activism vocabulary covers social movements, demonstrations, and civil disobedience at B2.","culturalNote":"Germany has a strong protest culture: Frieden movement (1980s), Anti-AKW movement, Fridays for Future, housing protest movements. The right to demonstrate (Demonstrationsfreiheit = Versammlungsfreiheit) is protected in Art. 8 GG. Key concepts: ziviler Ungehorsam (civil disobedience), Sit-in, Blockade, Petition, Boykott. The Polizeigesetz regulates demonstrations."},"examples":[{"german":"Soziale Bewegungen entstehen oft aus einem Gefühl der Ungerechtigkeit und dem Wunsch nach grundlegendem Wandel.","english":"Social movements often arise from a sense of injustice and the desire for fundamental change."},{"german":"Ziviler Ungehorsam ist eine Form des Protests, die bewusst Gesetze übertritt, um auf Missstände aufmerksam zu machen.","english":"Civil disobedience is a form of protest that deliberately transgresses laws in order to draw attention to grievances."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social movements, protest, and civil disobedience at B2."}}',
'{"items":[{"word":"der zivile Ungehorsam","translation":"civil disobedience","pronunciation":"dayr tsi-VEE-leh OON-geh-hor-zahm","example":"Ziviler Ungehorsam."},{"word":"übertreten","translation":"to transgress/violate","pronunciation":"ü-ber-TRAY-ten","example":"Gesetze übertreten."},{"word":"der Missstand","translation":"grievance/abuse/shortcoming","pronunciation":"dayr MIS-shtant","example":"Missstände aufzeigen."},{"word":"aufmerksam machen auf","translation":"to draw attention to","pronunciation":"OWF-merk-zahm MAH-khen owf","example":"Auf Missstände aufmerksam machen."},{"word":"der Wandel","translation":"change/transformation","pronunciation":"dayr VAN-del","example":"Grundlegender Wandel."},{"word":"bewusst","translation":"deliberately/consciously","pronunciation":"beh-VOOST","example":"Bewusst übertreten."}]}',
'{"title":"Aufmerksam machen auf — to draw attention to","pattern":"jemanden/etwas auf + accusative aufmerksam machen = to draw attention to (separable phrase)","explanation":"Auf etwas aufmerksam machen = to draw attention to something. Jemanden auf etwas aufmerksam machen = to point something out to someone. Auf Missstände aufmerksam machen = to draw attention to grievances. Passive: auf etwas aufmerksam gemacht werden = to have one''s attention drawn to something. Compare: hinweisen auf (to point out/indicate — more formal document language), betonen (to emphasise — more content), hervorheben (to highlight).","examples":[{"sentence":"Der Artikel macht auf die Risiken aufmerksam.","translation":"The article draws attention to the risks."},{"sentence":"Bitte machen Sie mich auf Fehler aufmerksam.","translation":"Please draw my attention to any errors."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Missstand'' means?","options":["grievance/abuse/shortcoming","mistake","problem","injustice"],"correctAnswer":"grievance/abuse/shortcoming"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Civil disobedience is a form of protest that deliberately transgresses laws in order to draw attention to grievances.","options":["Ziviler Ungehorsam ist eine Form des Protests, die bewusst Gesetze übertritt, um auf Missstände aufmerksam zu machen.","Ziviler Ungehorsam bricht das Gesetz, um Aufmerksamkeit zu erzeugen.","Durch Gesetzesübertretung macht man auf Missstände aufmerksam.","Protest kann auch durch Gesetzesübertretung ausgeübt werden."],"correctAnswer":"Ziviler Ungehorsam ist eine Form des Protests, die bewusst Gesetze übertritt, um auf Missstände aufmerksam zu machen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Artikel macht auf die Risiken ___.","options":["aufmerksam","hin","hinweisend","aufmerksam macht"],"correctAnswer":"aufmerksam"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Please draw my attention to any errors","wordBankItems":["Bitte","machen","Sie","mich","auf","Fehler","aufmerksam","."],"correctAnswer":"Bitte machen Sie mich auf Fehler aufmerksam ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bewusst'' means?","options":["deliberately/consciously","knowingly","purposely","intentionally"],"correctAnswer":"deliberately/consciously"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001aa',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss international politics at B2","Use internationale Politik vocabulary","Talk about multilateralism and power"],"explanation":{"intro":"International politics vocabulary covers multilateralism, power dynamics, and global governance at B2.","culturalNote":"Germany''s Außenpolitik is characterised by Multilateralismus (multilateralism), EU integration, and NATO membership. Key concepts: Außenpolitik durch Handel (change through trade — Wandel durch Handel, now questioned after Russia-Ukraine war), Bündnispolitik (alliance policy), Souveränitätsverzicht (sovereignty pooling in EU). The Außenministerium (Foreign Ministry — Auswärtiges Amt) coordinates policy."},"examples":[{"german":"Das Prinzip des Multilateralismus setzt auf internationale Zusammenarbeit und gemeinsame Regelwerke statt auf nationale Alleingänge.","english":"The principle of multilateralism relies on international cooperation and common regulatory frameworks instead of national go-it-alone approaches."},{"german":"Geopolitische Verschiebungen zwingen viele Länder, ihre außenpolitischen Strategien grundlegend zu überdenken.","english":"Geopolitical shifts are forcing many countries to fundamentally reconsider their foreign policy strategies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss international politics, multilateralism, and geopolitics at B2."}}',
'{"items":[{"word":"der Multilateralismus","translation":"multilateralism","pronunciation":"dayr mool-tee-lah-teh-rah-LIS-moos","example":"Multilateralismus."},{"word":"der Alleingang","translation":"go-it-alone approach","pronunciation":"dayr ah-LYN-gang","example":"Nationale Alleingänge."},{"word":"das Regelwerk","translation":"regulatory framework/ruleset","pronunciation":"dahs RAY-gel-verk","example":"Gemeinsames Regelwerk."},{"word":"geopolitisch","translation":"geopolitical","pronunciation":"geh-oh-po-LEE-tish","example":"Geopolitische Lage."},{"word":"die Verschiebung","translation":"shift/displacement","pronunciation":"dee fer-SHEE-boong","example":"Geopolitische Verschiebungen."},{"word":"zwingen","translation":"to force/compel","pronunciation":"TSVING-en","example":"Zu etwas zwingen."}]}',
'{"title":"Zwingen zu — to force/compel to do","pattern":"jemanden zu + dative zwingen = to force someone to (do something — compel)","explanation":"Zwingen zu + dative (with Infinitiv + zu in the full construction) = to force/compel to. Die Lage zwingt uns zu Maßnahmen = The situation forces us to take measures. Jemanden zwingen, etwas zu tun = to force someone to do something (Infinitiv construction). Perfect: hat gezwungen. Sich gezwungen sehen (zu) = to feel forced (to). Zwang = compulsion, coercion (noun).","examples":[{"sentence":"Die Krise zwang das Unternehmen, Kosten zu senken.","translation":"The crisis forced the company to cut costs."},{"sentence":"Ich sehe mich gezwungen, das Projekt abzubrechen.","translation":"I feel forced to abandon the project."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Alleingang'' means?","options":["go-it-alone approach","solo act","unilateral action","single path"],"correctAnswer":"go-it-alone approach"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The principle of multilateralism relies on international cooperation and common regulatory frameworks instead of national go-it-alone approaches.","options":["Das Prinzip des Multilateralismus setzt auf internationale Zusammenarbeit und gemeinsame Regelwerke statt auf nationale Alleingänge.","Multilateralismus bedeutet internationale Zusammenarbeit.","Statt national zu handeln setzt man auf internationale Kooperation.","Multilateralismus ist besser als Nationalismus."],"correctAnswer":"Das Prinzip des Multilateralismus setzt auf internationale Zusammenarbeit und gemeinsame Regelwerke statt auf nationale Alleingänge."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise zwang das Unternehmen, Kosten zu ___.","options":["senken","senkend","gesenkt","sinken"],"correctAnswer":"senken"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I feel forced to abandon the project","wordBankItems":["Ich","sehe","mich","gezwungen",",","das","Projekt","abzubrechen","."],"correctAnswer":"Ich sehe mich gezwungen , das Projekt abzubrechen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verschiebung'' means?","options":["shift/displacement","movement","change","transition"],"correctAnswer":"shift/displacement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ab',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss diplomacy at B2","Use Diplomatie vocabulary","Talk about negotiations and diplomatic relations"],"explanation":{"intro":"Diplomacy vocabulary covers bilateral and multilateral relations, diplomatic protocol, and conflict resolution at B2.","culturalNote":"Germany is a major diplomatic power. Key concepts: bilaterale Beziehungen (bilateral relations), multilaterales Forum (multilateral forum), Botschaft (embassy), Konsulat (consulate), Botschafter (ambassador), Außenminister (Foreign Minister). Germany chairs the G7 presidency periodically. The OSCE, OSZE in German (Organisation für Sicherheit und Zusammenarbeit in Europa), is important for conflict prevention."},"examples":[{"german":"Diplomatie zielt darauf ab, Konflikte durch Dialog und Verhandlungen beizulegen, bevor sie eskalieren.","english":"Diplomacy aims to resolve conflicts through dialogue and negotiations before they escalate."},{"german":"Bilaterale Beziehungen werden durch eine Vielzahl von Abkommen, Verträgen und regelmäßigen Konsultationen gestaltet.","english":"Bilateral relations are shaped by a variety of agreements, treaties, and regular consultations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss diplomacy, bilateral relations, and conflict resolution at B2."}}',
'{"items":[{"word":"beilegen","translation":"to resolve/settle (a conflict)","pronunciation":"BY-lay-gen","example":"Einen Konflikt beilegen."},{"word":"bilateral","translation":"bilateral","pronunciation":"bee-lah-teh-RAHL","example":"Bilaterale Beziehungen."},{"word":"die Vielzahl","translation":"variety/multitude","pronunciation":"dee FEEL-tsahl","example":"Eine Vielzahl von."},{"word":"das Abkommen","translation":"agreement/accord","pronunciation":"dahs AP-kom-en","example":"Ein Abkommen schließen."},{"word":"eskalieren","translation":"to escalate","pronunciation":"es-kah-LEER-en","example":"Nicht eskalieren lassen."},{"word":"die Konsultation","translation":"consultation","pronunciation":"dee kon-zool-tah-tsee-OHN","example":"Regelmäßige Konsultationen."}]}',
'{"title":"Darauf abzielen — to aim at/to (separable, purposive)","pattern":"etwas zielt darauf ab, + infinitive = something aims to, is aimed at","explanation":"Darauf abzielen, zu + Infinitiv = to aim to, to be aimed at. Diplomatie zielt darauf ab, Konflikte beizulegen = Diplomacy aims to resolve conflicts. Separable: zielt...ab. Perfect: hat darauf abgezielt. Also: das Ziel verfolgen, etwas zu tun (to pursue the goal of doing something — more formal/deliberate). The construction expresses intent of a policy, strategy, or entity.","examples":[{"sentence":"Die Reform zielt darauf ab, Bürokratie zu reduzieren.","translation":"The reform aims to reduce bureaucracy."},{"sentence":"Das Projekt zielt darauf ab, benachteiligte Jugendliche zu fördern.","translation":"The project aims to support disadvantaged young people."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Beilegen'' in conflict context means?","options":["to resolve/settle","to lay aside","to enclose","to add"],"correctAnswer":"to resolve/settle"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Diplomacy aims to resolve conflicts through dialogue and negotiations before they escalate.","options":["Diplomatie zielt darauf ab, Konflikte durch Dialog und Verhandlungen beizulegen, bevor sie eskalieren.","Diplomatie löst Konflikte durch Gespräche.","Durch Diplomatie werden Konflikte gelöst.","Diplomatie verhindert Eskalation."],"correctAnswer":"Diplomatie zielt darauf ab, Konflikte durch Dialog und Verhandlungen beizulegen, bevor sie eskalieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Reform zielt darauf ab, Bürokratie zu ___.","options":["reduzieren","reduziert","zu verringern","abbauen"],"correctAnswer":"reduzieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project aims to support disadvantaged young people","wordBankItems":["Das","Projekt","zielt","darauf","ab",",","benachteiligte","Jugendliche","zu","fördern","."],"correctAnswer":"Das Projekt zielt darauf ab , benachteiligte Jugendliche zu fördern ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Vielzahl'' means?","options":["variety/multitude","many","large number","plurality"],"correctAnswer":"variety/multitude"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ac',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss war and peace at B2","Use Krieg und Frieden vocabulary","Talk about conflict, security, and reconciliation"],"explanation":{"intro":"War and peace vocabulary covers conflict causes, humanitarian law, and peace processes at B2.","culturalNote":"Germany''s Sicherheitspolitik is shaped by historical Verantwortung (responsibility). Post-WWII: Germany was Zivilist (civilian power), rejecting military power politics. Russia''s invasion of Ukraine 2022 triggered a Zeitenwende (turning point — Scholz speech) — Germany increased defence spending dramatically. Key concepts: humanitäres Völkerrecht (international humanitarian law), Waffenstillstand (ceasefire), Friedensprozess (peace process)."},"examples":[{"german":"Der Schutz der Zivilbevölkerung ist ein grundlegendes Prinzip des humanitären Völkerrechts.","english":"The protection of the civilian population is a fundamental principle of international humanitarian law."},{"german":"Nachhaltige Friedensprozesse erfordern nicht nur das Ende der Kampfhandlungen, sondern auch Versöhnung und Wiederaufbau.","english":"Sustainable peace processes require not only an end to hostilities but also reconciliation and reconstruction."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss war, peace, international humanitarian law, and peace processes at B2."}}',
'{"items":[{"word":"das humanitäre Völkerrecht","translation":"international humanitarian law","pronunciation":"dahs hoo-mah-nee-TÄ-reh FÖL-ker-rekht","example":"Humanitäres Völkerrecht."},{"word":"die Versöhnung","translation":"reconciliation","pronunciation":"dee fer-ZÖ-noong","example":"Versöhnung und Wiederaufbau."},{"word":"die Kampfhandlung","translation":"hostilities/combat action","pronunciation":"dee KAMPF-hand-loong","example":"Kampfhandlungen."},{"word":"die Zeitenwende","translation":"turning point/new era","pronunciation":"dee TSYT-en-ven-deh","example":"Zeitenwende."},{"word":"der Waffenstillstand","translation":"ceasefire","pronunciation":"dayr VAF-en-shtil-shtant","example":"Waffenstillstand vereinbaren."},{"word":"nachhaltig","translation":"sustainable/lasting","pronunciation":"NAKH-hal-tikh","example":"Nachhaltige Lösung."}]}',
'{"title":"Nicht nur...sondern auch — not only...but also (additive)","pattern":"nicht nur X, sondern auch Y = not only X but also Y (additive, both elements are true)","explanation":"Nicht nur...sondern auch = not only...but also. Additive — both elements are affirmed. Erfordert nicht nur das Ende, sondern auch Versöhnung = Requires not only the end, but also reconciliation. Compare: nicht...sondern (corrective — only one is true). With nicht nur...sondern auch, BOTH are true: X und Y. This intensifies the claim by adding an extra element.","examples":[{"sentence":"Das Abkommen stärkt nicht nur die Wirtschaft, sondern auch die politischen Beziehungen.","translation":"The agreement strengthens not only the economy but also political relations."},{"sentence":"Er spricht nicht nur Deutsch, sondern auch Englisch und Spanisch.","translation":"He speaks not only German, but also English and Spanish."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Zeitenwende'' means?","options":["turning point/new era","turning of time","watershed moment","era shift"],"correctAnswer":"turning point/new era"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Sustainable peace processes require not only an end to hostilities but also reconciliation and reconstruction.","options":["Nachhaltige Friedensprozesse erfordern nicht nur das Ende der Kampfhandlungen, sondern auch Versöhnung und Wiederaufbau.","Frieden braucht mehr als nur Waffenstillstand.","Für dauerhaften Frieden braucht man Versöhnung.","Friedensprozesse sind komplex und langwierig."],"correctAnswer":"Nachhaltige Friedensprozesse erfordern nicht nur das Ende der Kampfhandlungen, sondern auch Versöhnung und Wiederaufbau."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Abkommen stärkt nicht nur die Wirtschaft, sondern ___ die politischen Beziehungen.","options":["auch","außerdem","zudem","darüber hinaus"],"correctAnswer":"auch"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He speaks not only German but also English and Spanish","wordBankItems":["Er","spricht","nicht","nur","Deutsch",",","sondern","auch","Englisch","und","Spanisch","."],"correctAnswer":"Er spricht nicht nur Deutsch , sondern auch Englisch und Spanisch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Waffenstillstand'' means?","options":["ceasefire","peace treaty","armistice","truce"],"correctAnswer":"ceasefire"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ad',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss security policy at B2","Use Sicherheitspolitik vocabulary","Talk about NATO and collective defence"],"explanation":{"intro":"Security policy vocabulary covers collective defence, NATO, and security strategy at B2.","culturalNote":"Germany is a NATO member since 1955. The Bundeswehr (armed forces) has ~183,000 soldiers. Controversies: Wehrpflicht abgeschafft (conscription abolished 2011, now debated again), Rüstungsexporte (arms exports — controversial), 2% NATO spending target (long missed, now met after Zeitenwende). Germany''s Nationale Sicherheitsstrategie was published for the first time in 2023."},"examples":[{"german":"Kollektive Verteidigung im Rahmen des NATO-Bündnisses beruht auf dem Prinzip: Angriff auf einen gilt als Angriff auf alle.","english":"Collective defence within the NATO alliance rests on the principle: an attack on one is regarded as an attack on all."},{"german":"Die Bundeswehr steht vor erheblichen Herausforderungen hinsichtlich Ausrüstung, Personal und strategischer Ausrichtung.","english":"The Bundeswehr faces considerable challenges regarding equipment, personnel, and strategic direction."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss security policy, NATO, and collective defence at B2."}}',
'{"items":[{"word":"kollektiv","translation":"collective","pronunciation":"ko-lek-TEEF","example":"Kollektive Verteidigung."},{"word":"die Ausrüstung","translation":"equipment","pronunciation":"dee OWS-rüs-toong","example":"Ausrüstung der Bundeswehr."},{"word":"die Ausrichtung","translation":"orientation/direction","pronunciation":"dee OWS-rikh-toong","example":"Strategische Ausrichtung."},{"word":"hinsichtlich","translation":"regarding/with respect to","pronunciation":"HIN-zikht-likh","example":"Hinsichtlich der Kosten."},{"word":"das Bündnis","translation":"alliance","pronunciation":"dahs BÜND-nis","example":"NATO-Bündnis."},{"word":"gelten als","translation":"to be regarded as","pronunciation":"GEL-ten als","example":"Gilt als Angriff."}]}',
'{"title":"Im Rahmen von — within the framework of","pattern":"im Rahmen + genitive/von = within the framework of, as part of (formal scope marker)","explanation":"Im Rahmen von + dative (or genitive): within the framework of, as part of. Im Rahmen des NATO-Bündnisses = within the framework of the NATO alliance. Im Rahmen des Projekts = as part of the project. Im Rahmen der gesetzlichen Möglichkeiten = within the scope of the law. Very common in formal German as a scope-limiting phrase. Compare: innerhalb (within — often physical or temporal), im Kontext (in the context of — more analytical).","examples":[{"sentence":"Im Rahmen der Veranstaltung werden mehrere Workshops angeboten.","translation":"As part of the event, several workshops are being offered."},{"sentence":"Wir handeln im Rahmen unserer vertraglichen Verpflichtungen.","translation":"We are acting within the framework of our contractual obligations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Ausrichtung'' means?","options":["orientation/direction","alignment","focus","strategic aim"],"correctAnswer":"orientation/direction"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Collective defence within the NATO alliance rests on the principle: an attack on one is regarded as an attack on all.","options":["Kollektive Verteidigung im Rahmen des NATO-Bündnisses beruht auf dem Prinzip: Angriff auf einen gilt als Angriff auf alle.","NATO schützt alle Mitgliedstaaten gemeinsam.","Im NATO-Bündnis gilt gegenseitige Verteidigung.","Alle NATO-Staaten verteidigen sich gegenseitig."],"correctAnswer":"Kollektive Verteidigung im Rahmen des NATO-Bündnisses beruht auf dem Prinzip: Angriff auf einen gilt als Angriff auf alle."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Rahmen der Veranstaltung werden mehrere Workshops ___.","options":["angeboten","angeboten werden","anbieten","geboten"],"correctAnswer":"angeboten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are acting within the framework of our contractual obligations","wordBankItems":["Wir","handeln","im","Rahmen","unserer","vertraglichen","Verpflichtungen","."],"correctAnswer":"Wir handeln im Rahmen unserer vertraglichen Verpflichtungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hinsichtlich'' means?","options":["regarding/with respect to","concerning","about","in terms of"],"correctAnswer":"regarding/with respect to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ae',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the United Nations at B2","Use UN vocabulary","Talk about international organisations"],"explanation":{"intro":"United Nations vocabulary covers the UN system, its bodies, and Germany''s role at B2.","culturalNote":"Germany joined the UN in 1973. Germany contributes significantly to UN peacekeeping (Friedensmissionen) and development aid. Key UN bodies: Sicherheitsrat (Security Council), Generalversammlung (General Assembly), Internationaler Strafgerichtshof (ICC — Internationaler Strafgerichtshof). Germany supports multilateralism and international law strongly."},"examples":[{"german":"Der UN-Sicherheitsrat trägt die Hauptverantwortung für die Aufrechterhaltung des Weltfriedens und der internationalen Sicherheit.","english":"The UN Security Council bears primary responsibility for the maintenance of world peace and international security."},{"german":"Das Vetorecht der fünf ständigen Mitglieder des Sicherheitsrats wird oft als Hindernis für wirksames multilaterales Handeln kritisiert.","english":"The veto right of the five permanent members of the Security Council is often criticised as an obstacle to effective multilateral action."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the UN system, Security Council, and international organisations at B2."}}',
'{"items":[{"word":"die Aufrechterhaltung","translation":"maintenance/upholding","pronunciation":"dee OWF-rekht-er-hal-toong","example":"Aufrechterhaltung des Friedens."},{"word":"ständig","translation":"permanent/constant","pronunciation":"SHTEN-dikh","example":"Ständige Mitglieder."},{"word":"das Vetorecht","translation":"veto right","pronunciation":"dahs VAY-toh-rekht","example":"Vetorecht."},{"word":"das Hindernis","translation":"obstacle","pronunciation":"dahs HIN-der-nis","example":"Als Hindernis gelten."},{"word":"wirksam","translation":"effective","pronunciation":"VIRK-zahm","example":"Wirksames Handeln."},{"word":"tragen","translation":"to bear/carry","pronunciation":"TRAH-gen","example":"Verantwortung tragen."}]}',
'{"title":"Verantwortung tragen für — to bear responsibility for","pattern":"die Verantwortung tragen für + accusative = to bear responsibility for (formal, institutional)","explanation":"Die Verantwortung tragen (für) = to bear responsibility (for). Der Sicherheitsrat trägt die Hauptverantwortung = The Security Council bears primary responsibility. Tragen with abstract nouns: die Last tragen (to bear the burden), das Risiko tragen (to bear the risk), die Kosten tragen (to bear the costs). Verantwortung übernehmen = to take on/assume responsibility (more active, voluntary). Verantwortung abwälzen = to shift responsibility (negative).","examples":[{"sentence":"Jeder Mitarbeiter trägt Verantwortung für die Qualität seiner Arbeit.","translation":"Every employee bears responsibility for the quality of their work."},{"sentence":"Wer trägt die Kosten für diesen Schaden?","translation":"Who bears the costs for this damage?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ständig'' as an adjective in ''ständige Mitglieder'' means?","options":["permanent","constant","regular","standing"],"correctAnswer":"permanent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The UN Security Council bears primary responsibility for the maintenance of world peace and international security.","options":["Der UN-Sicherheitsrat trägt die Hauptverantwortung für die Aufrechterhaltung des Weltfriedens und der internationalen Sicherheit.","Der Sicherheitsrat ist für den Weltfrieden zuständig.","Die UN ist verantwortlich für Frieden.","Der Sicherheitsrat sorgt für internationale Sicherheit."],"correctAnswer":"Der UN-Sicherheitsrat trägt die Hauptverantwortung für die Aufrechterhaltung des Weltfriedens und der internationalen Sicherheit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Jeder Mitarbeiter trägt Verantwortung für die Qualität seiner ___.","options":["Arbeit","Leistung","Tätigkeit","Aufgabe"],"correctAnswer":"Arbeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Who bears the costs for this damage","wordBankItems":["Wer","trägt","die","Kosten","für","diesen","Schaden","?"],"correctAnswer":"Wer trägt die Kosten für diesen Schaden ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Hindernis'' means?","options":["obstacle","barrier","impediment","hurdle"],"correctAnswer":"obstacle"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001af',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urbanisation at B2","Use Urbanisierung vocabulary","Talk about city growth and challenges"],"explanation":{"intro":"Urbanisation vocabulary covers city growth, urban planning, and urban challenges at B2.","culturalNote":"Germany is highly urbanised (77%) but also has many strong medium-sized cities (Mittelstädte). Berlin, Hamburg, Munich, Cologne are the major centres. Key issues: Gentrifizierung (gentrification), bezahlbarer Wohnraum (affordable housing), Verkehrswende (transport transition), Schwammstadt (sponge city — flood resilience), Stadtbegrünung (urban greening)."},"examples":[{"german":"Gentrifizierung verändert Stadtviertel grundlegend: Alteingesessene werden verdrängt, während die Infrastruktur aufgewertet wird.","english":"Gentrification fundamentally transforms neighbourhoods: long-established residents are displaced while the infrastructure is upgraded."},{"german":"Nachhaltige Stadtentwicklung muss ökologische, soziale und wirtschaftliche Aspekte in Einklang bringen.","english":"Sustainable urban development must reconcile ecological, social, and economic aspects."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss urbanisation, gentrification, and urban development at B2."}}',
'{"items":[{"word":"die Gentrifizierung","translation":"gentrification","pronunciation":"dee gen-tri-fi-TSEE-roong","example":"Gentrifizierung."},{"word":"alteingesessen","translation":"long-established/old-established","pronunciation":"ALT-yn-geh-zes-en","example":"Alteingesessene Bewohner."},{"word":"verdrängen","translation":"to displace/push out","pronunciation":"fer-DRENG-en","example":"Verdrängt werden."},{"word":"aufwerten","translation":"to upgrade/enhance","pronunciation":"OWF-ver-ten","example":"Die Infrastruktur aufwerten."},{"word":"in Einklang bringen","translation":"to reconcile/harmonise","pronunciation":"in YN-klang BRING-en","example":"In Einklang bringen."},{"word":"die Stadtentwicklung","translation":"urban development","pronunciation":"dee SHTAT-ent-vik-loong","example":"Stadtentwicklung."}]}',
'{"title":"In Einklang bringen — to reconcile/harmonise","pattern":"etwas in Einklang bringen mit + dative = to bring into harmony with, reconcile","explanation":"In Einklang bringen mit = to reconcile, bring into harmony with. Wirtschaft in Einklang bringen mit Umwelt = to reconcile economy with environment. In Einklang stehen mit = to be in harmony/accordance with. Der Einklang = harmony, accord. Compare: vereinbaren (to combine/reconcile — more everyday), ausbalancieren (to balance — more physical), unter einen Hut bringen (to combine/reconcile — colloquial idiom).","examples":[{"sentence":"Die Anforderungen lassen sich nur schwer in Einklang bringen.","translation":"The requirements can only be reconciled with difficulty."},{"sentence":"Ihr Aussagen stehen nicht in Einklang mit den Fakten.","translation":"Your statements are not in accord with the facts."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace/push out","to suppress","to replace","to force away"],"correctAnswer":"to displace/push out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gentrification fundamentally transforms neighbourhoods: long-established residents are displaced while the infrastructure is upgraded.","options":["Gentrifizierung verändert Stadtviertel grundlegend: Alteingesessene werden verdrängt, während die Infrastruktur aufgewertet wird.","Gentrifizierung bedeutet Modernisierung auf Kosten der Alteingesessenen.","Wenn Infrastruktur aufgewertet wird, werden Alteingesessene verdrängt.","Durch Gentrifizierung verändert sich das Stadtbild."],"correctAnswer":"Gentrifizierung verändert Stadtviertel grundlegend: Alteingesessene werden verdrängt, während die Infrastruktur aufgewertet wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Anforderungen lassen sich nur schwer in Einklang ___.","options":["bringen","kommen","setzen","stellen"],"correctAnswer":"bringen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Your statements are not in accord with the facts","wordBankItems":["Ihr","Aussagen","stehen","nicht","in","Einklang","mit","den","Fakten","."],"correctAnswer":"Ihr Aussagen stehen nicht in Einklang mit den Fakten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Alteingesessen'' means?","options":["long-established/old-established","old-fashioned","traditional","native"],"correctAnswer":"long-established/old-established"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss infrastructure at B2","Use Infrastruktur vocabulary","Talk about public investment and maintenance"],"explanation":{"intro":"Infrastructure vocabulary covers transport, digital infrastructure, and public investment at B2.","culturalNote":"Germany faces an Infrastrukturkrise: ageing bridges (Leverkusener Brücke), train delays (Bahn-Pünktlichkeit), slow Breitbandausbau (broadband expansion), and underfunded Kommunen (municipalities). The Deutschlandticket (49€/month public transport) was introduced in 2023. Infrastructure investment gap (Investitionslücke) is a major political debate."},"examples":[{"german":"Die marode Infrastruktur in vielen Teilen Deutschlands ist das Ergebnis jahrzehntelanger Vernachlässigung öffentlicher Investitionen.","english":"The crumbling infrastructure in many parts of Germany is the result of decades of neglect of public investment."},{"german":"Ein leistungsfähiges Verkehrsnetz ist eine Grundvoraussetzung für wirtschaftliche Wettbewerbsfähigkeit.","english":"An efficient transport network is a fundamental prerequisite for economic competitiveness."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss infrastructure, public investment, and transport networks at B2."}}',
'{"items":[{"word":"marode","translation":"crumbling/decrepit","pronunciation":"mah-ROH-deh","example":"Marode Infrastruktur."},{"word":"die Vernachlässigung","translation":"neglect","pronunciation":"dee fer-NAKH-läs-ee-goong","example":"Vernachlässigung."},{"word":"leistungsfähig","translation":"efficient/high-performing","pronunciation":"LYS-toonks-fä-ikh","example":"Leistungsfähiges Netz."},{"word":"die Wettbewerbsfähigkeit","translation":"competitiveness","pronunciation":"dee VET-beh-verbs-fä-ikh-kyt","example":"Wirtschaftliche Wettbewerbsfähigkeit."},{"word":"die Investitionslücke","translation":"investment gap","pronunciation":"dee in-ves-tee-tsyohns-lük-eh","example":"Investitionslücke."},{"word":"das Ergebnis","translation":"result/outcome","pronunciation":"dahs er-GEB-nis","example":"Das Ergebnis."}]}',
'{"title":"Das Ergebnis von/einer Sache sein — to be the result of","pattern":"etwas ist das Ergebnis + genitive = something is the result of (formal noun-based causation)","explanation":"Das Ergebnis + genitive = the result of. Die Krise ist das Ergebnis jahrelanger Vernachlässigung = The crisis is the result of years of neglect. More formal than: entstand durch, ist entstanden aus. The nominalized construction is typical of academic and journalistic German. Compare: die Folge (consequence/result — slightly different — follows as a consequence), die Konsequenz (consequence — more deliberate), das Resultat (result — more technical/formal).","examples":[{"sentence":"Dieses Problem ist das Ergebnis fehlender Planung.","translation":"This problem is the result of inadequate planning."},{"sentence":"Ihr Erfolg ist das Ergebnis harter Arbeit.","translation":"Her success is the result of hard work."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Marode'' means?","options":["crumbling/decrepit","worn-out","damaged","dilapidated"],"correctAnswer":"crumbling/decrepit"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The crumbling infrastructure in many parts of Germany is the result of decades of neglect of public investment.","options":["Die marode Infrastruktur in vielen Teilen Deutschlands ist das Ergebnis jahrzehntelanger Vernachlässigung öffentlicher Investitionen.","Deutschlands Infrastruktur ist veraltet wegen mangelnder Investitionen.","Öffentliche Investitionen wurden vernachlässigt, daher ist die Infrastruktur marode.","Die Infrastruktur leidet unter jahrzehntelanger Vernachlässigung."],"correctAnswer":"Die marode Infrastruktur in vielen Teilen Deutschlands ist das Ergebnis jahrzehntelanger Vernachlässigung öffentlicher Investitionen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dieses Problem ist das Ergebnis fehlender ___.","options":["Planung","Pläne","Planungen","Plan"],"correctAnswer":"Planung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Her success is the result of hard work","wordBankItems":["Ihr","Erfolg","ist","das","Ergebnis","harter","Arbeit","."],"correctAnswer":"Ihr Erfolg ist das Ergebnis harter Arbeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Leistungsfähig'' means?","options":["efficient/high-performing","capable","powerful","productive"],"correctAnswer":"efficient/high-performing"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss housing policy at B2","Use Wohnungspolitik vocabulary","Talk about housing shortage and affordability"],"explanation":{"intro":"Housing policy vocabulary covers rent regulation, housing shortages, and urban affordability at B2.","culturalNote":"Germany has a serious Wohnungskrise (housing crisis) in major cities. Miete (rent) takes up ~30%+ of income in Berlin/Munich. Key policies: Mietpreisbremse (rent brake), Sozialwohnungen (social housing), Wohnungsbaugesellschaft (housing association). Neubau (new construction) has stalled due to high interest rates and construction costs. NIMBYism (Nicht-in-meinem-Garten = not in my backyard) hinders construction."},"examples":[{"german":"Der angespannte Wohnungsmarkt in deutschen Großstädten ist vor allem auf mangelndes Angebot und steigende Nachfrage zurückzuführen.","english":"The strained housing market in German cities is primarily attributable to inadequate supply and rising demand."},{"german":"Ohne deutlich mehr bezahlbaren Wohnraum droht eine weitere Verschärfung der sozialen Segregation.","english":"Without significantly more affordable housing, a further intensification of social segregation looms."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss housing policy, rent regulation, and housing shortage at B2."}}',
'{"items":[{"word":"angespannt","translation":"strained/tense","pronunciation":"AN-geh-shpant","example":"Angespannter Markt."},{"word":"zurückführen auf","translation":"to attribute to","pronunciation":"tsoo-RÜK-füh-ren owf","example":"Auf Ursachen zurückführen."},{"word":"drohen","translation":"to loom/threaten","pronunciation":"DROH-en","example":"Etwas droht."},{"word":"die Segregation","translation":"segregation","pronunciation":"dee zeh-greh-gah-tsee-OHN","example":"Soziale Segregation."},{"word":"der Wohnraum","translation":"living space/housing","pronunciation":"dayr VOHN-rowm","example":"Bezahlbarer Wohnraum."},{"word":"mangeln","translation":"to be lacking/inadequate","pronunciation":"MANG-eln","example":"Es mangelt an Angebot."}]}',
'{"title":"Zurückführen auf — to attribute to / trace back to","pattern":"etwas zurückführen auf + accusative = to attribute to, trace back to (separable)","explanation":"Zurückführen auf + accusative = to attribute to, trace back to. Das Problem ist auf X zurückzuführen = The problem is attributable to X (infinitive with zu). Active: Man führt das Problem auf X zurück. Passive: Das Problem wird auf X zurückgeführt. Perfect: hat zurückgeführt. The construction attributes causes. Compare: zuschreiben (to attribute — more personal credit/blame), zurechnen (to attribute/charge — accounting/legal).","examples":[{"sentence":"Das Scheitern des Projekts ist auf Kommunikationsprobleme zurückzuführen.","translation":"The failure of the project is attributable to communication problems."},{"sentence":"Die Krankheit kann auf mehrere Ursachen zurückgeführt werden.","translation":"The illness can be traced back to several causes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Angespannt'' means?","options":["strained/tense","tight","pressured","stressed"],"correctAnswer":"strained/tense"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The strained housing market in German cities is primarily attributable to inadequate supply and rising demand.","options":["Der angespannte Wohnungsmarkt in deutschen Großstädten ist vor allem auf mangelndes Angebot und steigende Nachfrage zurückzuführen.","Der Wohnungsmarkt ist angespannt wegen zu wenig Wohnungen.","Mangelndes Angebot verursacht die Wohnungskrise.","Der Wohnungsmarkt leidet unter steigender Nachfrage."],"correctAnswer":"Der angespannte Wohnungsmarkt in deutschen Großstädten ist vor allem auf mangelndes Angebot und steigende Nachfrage zurückzuführen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Scheitern des Projekts ist auf Kommunikationsprobleme ___.","options":["zurückzuführen","zurückgeführt","zurückzuführen ist","zurückführend"],"correctAnswer":"zurückzuführen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The illness can be traced back to several causes","wordBankItems":["Die","Krankheit","kann","auf","mehrere","Ursachen","zurückgeführt","werden","."],"correctAnswer":"Die Krankheit kann auf mehrere Ursachen zurückgeführt werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Drohen'' in ''es droht eine Verschärfung'' means?","options":["to loom/threaten (impersonal)","to threaten someone","to warn","to impend"],"correctAnswer":"to loom/threaten (impersonal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss future mobility at B2","Use Mobilität vocabulary","Talk about transport transitions"],"explanation":{"intro":"Future mobility vocabulary covers autonomous vehicles, e-mobility, and transport policy at B2.","culturalNote":"Germany''s Verkehrswende (transport transition) aims to shift from car to public transport, cycling, and rail. Key concepts: Antriebswende (powertrain transition — electric/hydrogen), autonomes Fahren (autonomous driving), Sharing Economy in transport (car sharing, e-scooters), 49-Euro-Ticket. Germany is the home of the Autoindustrie (auto industry) — BMW, Mercedes, VW — making the Verkehrswende politically complex."},"examples":[{"german":"Die Transformation des Verkehrssystems erfordert massive Investitionen in Schieneninfrastruktur und öffentliche Verkehrsmittel.","english":"The transformation of the transport system requires massive investment in rail infrastructure and public transport."},{"german":"Autonomes Fahren verspricht mehr Sicherheit und Effizienz, wirft aber auch neue ethische und rechtliche Fragen auf.","english":"Autonomous driving promises greater safety and efficiency, but also raises new ethical and legal questions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss future mobility, transport transitions, and autonomous vehicles at B2."}}',
'{"items":[{"word":"die Schiene","translation":"rail/track","pronunciation":"dee SHEE-neh","example":"Schieneninfrastruktur."},{"word":"versprechen","translation":"to promise","pronunciation":"fer-SHPREKH-en","example":"Mehr Sicherheit versprechen."},{"word":"aufwerfen","translation":"to raise (questions/issues)","pronunciation":"OWF-ver-fen","example":"Fragen aufwerfen."},{"word":"autonom","translation":"autonomous","pronunciation":"ow-to-NOHM","example":"Autonomes Fahren."},{"word":"die Transformation","translation":"transformation","pronunciation":"dee trans-for-mah-tsee-OHN","example":"Transformation des Systems."},{"word":"massiv","translation":"massive","pronunciation":"mas-SEEF","example":"Massive Investitionen."}]}',
'{"title":"Fragen aufwerfen — to raise questions","pattern":"Fragen aufwerfen = to raise questions (separable — throw up questions, pose issues)","explanation":"Fragen aufwerfen (separable) = to raise questions, throw up issues. Das Experiment wirft neue Fragen auf = The experiment raises new questions. Perfect: hat aufgeworfen. Also: Probleme aufwerfen (to raise problems), Zweifel aufwerfen (to raise doubts). Compare: Fragen stellen (to ask questions — more transitive), Fragen aufkommen lassen (to let questions arise), Bedenken äußern (to voice concerns). Aufwerfen is more academic/journalistic.","examples":[{"sentence":"Diese Entscheidung wirft ernsthafte ethische Fragen auf.","translation":"This decision raises serious ethical questions."},{"sentence":"Die Ergebnisse werfen neue Fragen nach den Ursachen auf.","translation":"The results raise new questions about the causes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Schiene'' means?","options":["rail/track","tram","railway","line"],"correctAnswer":"rail/track"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Autonomous driving promises greater safety and efficiency, but also raises new ethical and legal questions.","options":["Autonomes Fahren verspricht mehr Sicherheit und Effizienz, wirft aber auch neue ethische und rechtliche Fragen auf.","Autonomes Fahren ist sicherer, aber es gibt Probleme.","Autonomes Fahren hat Vorteile und wirft Fragen auf.","Die Vorteile des autonomen Fahrens sind klar."],"correctAnswer":"Autonomes Fahren verspricht mehr Sicherheit und Effizienz, wirft aber auch neue ethische und rechtliche Fragen auf."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Entscheidung wirft ernsthafte ethische Fragen ___.","options":["auf","aus","an","ab"],"correctAnswer":"auf"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The results raise new questions about the causes","wordBankItems":["Die","Ergebnisse","werfen","neue","Fragen","nach","den","Ursachen","auf","."],"correctAnswer":"Die Ergebnisse werfen neue Fragen nach den Ursachen auf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Versprechen'' as a noun means?","options":["promise","commitment","pledge","guarantee"],"correctAnswer":"promise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss agriculture at B2","Use Landwirtschaft vocabulary","Talk about farming and food systems"],"explanation":{"intro":"Agriculture vocabulary covers farming systems, agri-policy, and food security at B2.","culturalNote":"Germany''s Landwirtschaft: 250,000 farms, declining in number. Key issues: Agrarsubventionen (EU farming subsidies — Common Agricultural Policy), Flächenversiegelung (soil sealing — development reduces farmland), Tierwohl (animal welfare), Pestizidreduktion (pesticide reduction), Biodiversitätsverlust (biodiversity loss in farmland). Organic farming (Ökolandbau) covers ~11% of farmland."},"examples":[{"german":"Intensive Landwirtschaft steigert zwar die Erträge, geht aber häufig auf Kosten von Biodiversität und Bodenqualität.","english":"Intensive agriculture increases yields, but it often comes at the cost of biodiversity and soil quality."},{"german":"Die Transformation hin zu einer nachhaltigen Landwirtschaft ist eine der größten Herausforderungen des 21. Jahrhunderts.","english":"The transformation towards sustainable agriculture is one of the greatest challenges of the 21st century."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss agricultural systems, food policy, and sustainability at B2."}}',
'{"items":[{"word":"der Ertrag","translation":"yield/output","pronunciation":"dayr er-TRAHK","example":"Erträge steigern."},{"word":"auf Kosten von","translation":"at the cost/expense of","pronunciation":"owf KOS-ten fon","example":"Auf Kosten der Umwelt."},{"word":"die Bodenqualität","translation":"soil quality","pronunciation":"dee BOH-den-kva-lee-tät","example":"Bodenqualität."},{"word":"die Agrarsubvention","translation":"agricultural subsidy","pronunciation":"dee ah-GRAHR-zoop-ven-tsyohn","example":"Agrarsubventionen."},{"word":"hin zu","translation":"towards","pronunciation":"hin tsoo","example":"Hin zu einer Lösung."},{"word":"intensiv","translation":"intensive","pronunciation":"in-ten-SEEF","example":"Intensive Landwirtschaft."}]}',
'{"title":"Auf Kosten von — at the cost/expense of","pattern":"auf Kosten + genitive/von = at the cost of, at the expense of","explanation":"Auf Kosten von/genitive = at the cost/expense of. Geht auf Kosten der Umwelt = comes at the cost of the environment. Auf eigene Kosten = at one''s own expense. Auf Kosten anderer = at others'' expense. The phrase marks a trade-off where one gain involves another''s loss. Common in critical analysis. Also: zulasten (at the expense of — single word, more formal legal/financial).","examples":[{"sentence":"Der Erfolg des Unternehmens ging auf Kosten der Mitarbeiter.","translation":"The company''s success came at the expense of the employees."},{"sentence":"Schnelles Wachstum geht häufig auf Kosten der Nachhaltigkeit.","translation":"Rapid growth often comes at the cost of sustainability."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Ertrag'' means?","options":["yield/output","return","profit","harvest"],"correctAnswer":"yield/output"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Intensive agriculture increases yields, but it often comes at the cost of biodiversity and soil quality.","options":["Intensive Landwirtschaft steigert zwar die Erträge, geht aber häufig auf Kosten von Biodiversität und Bodenqualität.","Intensive Landwirtschaft ist produktiv aber umweltschädlich.","Hohe Erträge gehen auf Kosten der Biodiversität.","Intensive Methoden schaden der Biodiversität."],"correctAnswer":"Intensive Landwirtschaft steigert zwar die Erträge, geht aber häufig auf Kosten von Biodiversität und Bodenqualität."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Erfolg des Unternehmens ging auf Kosten der ___.","options":["Mitarbeiter","Angestellten","Belegschaft","Arbeitnehmer"],"correctAnswer":"Mitarbeiter"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Rapid growth often comes at the cost of sustainability","wordBankItems":["Schnelles","Wachstum","geht","häufig","auf","Kosten","der","Nachhaltigkeit","."],"correctAnswer":"Schnelles Wachstum geht häufig auf Kosten der Nachhaltigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hin zu'' means?","options":["towards","to","in direction of","toward a goal"],"correctAnswer":"towards"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss food and sustainability at B2","Use Ernährung vocabulary","Talk about dietary choices and food systems"],"explanation":{"intro":"Food and sustainability vocabulary covers food systems, dietary choices, and sustainability at B2.","culturalNote":"Germany''s Ernährungswandel (dietary change): rising veganism/vegetarianism, Lebensmittelverschwendung (food waste — 11 million tonnes/year), Saisonal und regional einkaufen (seasonal and local buying), Biosiegel (organic labels), Tafeln (food banks). Meat consumption declining. Key EU policy: Farm to Fork Strategy (Vom Hof auf den Tisch)."},"examples":[{"german":"Lebensmittelverschwendung ist ein gravierendes Problem: Ein Drittel aller weltweit produzierten Nahrungsmittel geht verloren.","english":"Food waste is a serious problem: a third of all food produced globally is lost."},{"german":"Eine pflanzenbetonte Ernährung kann erheblich zur Reduzierung des ökologischen Fußabdrucks beitragen.","english":"A plant-based diet can contribute considerably to reducing the ecological footprint."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss food waste, dietary choices, and food sustainability at B2."}}',
'{"items":[{"word":"gravierend","translation":"serious/grave","pronunciation":"grah-VEER-end","example":"Gravierendes Problem."},{"word":"pflanzenbetont","translation":"plant-based/plant-focused","pronunciation":"PFLAN-tsen-beh-tohnt","example":"Pflanzenbetonte Ernährung."},{"word":"der Fußabdruck","translation":"footprint","pronunciation":"dayr FOOS-ap-drook","example":"Ökologischer Fußabdruck."},{"word":"beitragen zu","translation":"to contribute to","pronunciation":"BY-trah-gen tsoo","example":"Beitragen zur Lösung."},{"word":"die Lebensmittelverschwendung","translation":"food waste","pronunciation":"dee LAY-bens-mit-el-fer-shven-doong","example":"Lebensmittelverschwendung."},{"word":"verloren gehen","translation":"to be lost","pronunciation":"fer-LOH-ren GAY-en","example":"Verloren gehen."}]}',
'{"title":"Beitragen zu — to contribute to","pattern":"etwas trägt zu + dative bei (separable) = something contributes to","explanation":"Beitragen zu + dative (separable): etwas beiträgt zu = something contributes to. Eine pflanzenbetonte Ernährung trägt zur Reduzierung bei = A plant-based diet contributes to reduction. Perfect: hat beigetragen. Der Beitrag zu = contribution to. Also: leisten (einen Beitrag leisten zu = to make a contribution to — more formal deliberate action). Maßgeblich beitragen zu = to make a significant contribution to.","examples":[{"sentence":"Erneuerbare Energien tragen entscheidend zur Reduzierung der Emissionen bei.","translation":"Renewable energies contribute decisively to the reduction of emissions."},{"sentence":"Jeder kann seinen Teil zum Klimaschutz beitragen.","translation":"Everyone can contribute their part to climate protection."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gravierend'' means?","options":["serious/grave","grave","heavy","weighty"],"correctAnswer":"serious/grave"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Food waste is a serious problem: a third of all food produced globally is lost.","options":["Lebensmittelverschwendung ist ein gravierendes Problem: Ein Drittel aller weltweit produzierten Nahrungsmittel geht verloren.","Ein Drittel aller Lebensmittel wird verschwendet.","Lebensmittelverschwendung ist weltweit ein Problem.","Viele Nahrungsmittel gehen verloren."],"correctAnswer":"Lebensmittelverschwendung ist ein gravierendes Problem: Ein Drittel aller weltweit produzierten Nahrungsmittel geht verloren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Erneuerbare Energien tragen entscheidend zur Reduzierung der Emissionen ___.","options":["bei","aus","an","ein"],"correctAnswer":"bei"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Everyone can contribute their part to climate protection","wordBankItems":["Jeder","kann","seinen","Teil","zum","Klimaschutz","beitragen","."],"correctAnswer":"Jeder kann seinen Teil zum Klimaschutz beitragen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Pflanzenbetont'' means?","options":["plant-based/plant-focused","plant-heavy","vegetarian","vegan"],"correctAnswer":"plant-based/plant-focused"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health and prevention at B2","Use Gesundheitsprävention vocabulary","Talk about public health"],"explanation":{"intro":"Health and prevention vocabulary covers public health, lifestyle, and prevention at B2.","culturalNote":"Germany''s Präventionspolitik (prevention policy): Krankheitsprävention (disease prevention) saves costs in the long run. Key issues: Bewegungsmangel (lack of exercise), Übergewicht (obesity), Tabakkonsum (tobacco use), Alkoholmissbrauch, mentale Gesundheit (mental health — rising, increasingly destigmatised). The Prävention Act (Präventionsgesetz 2015) shifted focus to prevention."},"examples":[{"german":"Präventive Gesundheitsmaßnahmen sind langfristig kostengünstiger als die Behandlung bereits ausgebrochener Erkrankungen.","english":"Preventive health measures are more cost-effective in the long term than treating illnesses that have already broken out."},{"german":"Die Förderung psychischer Gesundheit gewinnt zunehmend an Bedeutung, da Burnout und Depressionen stark zunehmen.","english":"The promotion of mental health is increasingly gaining in importance, as burnout and depression are rising sharply."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss public health, prevention, and mental health at B2."}}',
'{"items":[{"word":"präventiv","translation":"preventive","pronunciation":"prä-ven-TEEF","example":"Präventive Maßnahmen."},{"word":"kostengünstig","translation":"cost-effective","pronunciation":"KOS-ten-güns-tikh","example":"Kostengünstig."},{"word":"ausbrechen","translation":"to break out (illness)","pronunciation":"OWS-brekh-en","example":"Ausgebrochene Erkrankung."},{"word":"zunehmen","translation":"to increase/rise","pronunciation":"TSOO-nay-men","example":"Stark zunehmen."},{"word":"an Bedeutung gewinnen","translation":"to gain in importance","pronunciation":"an beh-DOY-toong geh-VIN-en","example":"An Bedeutung gewinnen."},{"word":"die Förderung","translation":"promotion/support","pronunciation":"dee FÖR-deh-roong","example":"Förderung der Gesundheit."}]}',
'{"title":"An Bedeutung gewinnen — to gain in importance","pattern":"etwas gewinnt an Bedeutung = something gains in importance (gradual increase)","explanation":"An Bedeutung gewinnen = to gain in importance, become more important (gradual process). Etwas verliert an Bedeutung = something loses importance. An Bedeutung zunehmen (similar). Pattern: [subject] gewinnt an [abstract noun]. Other patterns: an Gewicht gewinnen (to gain weight/significance), an Einfluss verlieren (to lose influence). These constructions express gradual change in status of abstract qualities.","examples":[{"sentence":"Digitale Kompetenzen gewinnen auf dem Arbeitsmarkt zunehmend an Bedeutung.","translation":"Digital skills are increasingly gaining in importance on the labour market."},{"sentence":"Der Aspekt der Lebensqualität gewinnt in der Stadtplanung an Bedeutung.","translation":"The aspect of quality of life is gaining in importance in urban planning."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Präventiv'' means?","options":["preventive","precautionary","protective","proactive"],"correctAnswer":"preventive"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The promotion of mental health is increasingly gaining in importance, as burnout and depression are rising sharply.","options":["Die Förderung psychischer Gesundheit gewinnt zunehmend an Bedeutung, da Burnout und Depressionen stark zunehmen.","Mentale Gesundheit wird immer wichtiger.","Burnout und Depression nehmen zu, daher wird Prävention wichtiger.","Die psychische Gesundheit wird stärker gefördert."],"correctAnswer":"Die Förderung psychischer Gesundheit gewinnt zunehmend an Bedeutung, da Burnout und Depressionen stark zunehmen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Digitale Kompetenzen gewinnen auf dem Arbeitsmarkt zunehmend an ___.","options":["Bedeutung","Wert","Wichtigkeit","Relevanz"],"correctAnswer":"Bedeutung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The aspect of quality of life is gaining in importance in urban planning","wordBankItems":["Der","Aspekt","der","Lebensqualität","gewinnt","in","der","Stadtplanung","an","Bedeutung","."],"correctAnswer":"Der Aspekt der Lebensqualität gewinnt in der Stadtplanung an Bedeutung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausbrechen'' in medical context means?","options":["to break out (illness)","to escape","to erupt","to occur"],"correctAnswer":"to break out (illness)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss psychology at B2","Use Psychologie vocabulary","Talk about cognitive biases and behaviour"],"explanation":{"intro":"Psychology vocabulary covers cognitive biases, behaviour, and key concepts at B2.","culturalNote":"Psychology is a popular subject in Germany (Psychologiestudium). Key concepts: kognitive Verzerrungen (cognitive biases), Verhaltensökonomie (behavioural economics — Thaler/Kahneman widely read), Resilienz (resilience), Achtsamkeit (mindfulness — very popular in Germany), Prokrastination (procrastination). Psychotherapie is covered by Krankenkassen."},"examples":[{"german":"Kognitive Verzerrungen beeinflussen unsere Wahrnehmung und Entscheidungen, ohne dass wir uns dessen bewusst sind.","english":"Cognitive biases influence our perception and decisions without our being aware of it."},{"german":"Resilienz bezeichnet die Fähigkeit, trotz widriger Umstände psychisch stabil zu bleiben und sich von Rückschlägen zu erholen.","english":"Resilience denotes the ability to remain psychologically stable despite adverse circumstances and to recover from setbacks."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss psychology, cognitive biases, and resilience at B2."}}',
'{"items":[{"word":"die kognitive Verzerrung","translation":"cognitive bias","pronunciation":"dee kog-NEE-tee-veh fer-TSER-roong","example":"Kognitive Verzerrungen."},{"word":"die Resilienz","translation":"resilience","pronunciation":"dee reh-zi-lee-ENTS","example":"Resilienz stärken."},{"word":"widrig","translation":"adverse","pronunciation":"VEE-drikh","example":"Widrige Umstände."},{"word":"der Rückschlag","translation":"setback","pronunciation":"dayr RÜK-shlahk","example":"Von Rückschlägen erholen."},{"word":"bezeichnen","translation":"to denote/designate","pronunciation":"beh-TSYKH-nen","example":"Etwas als X bezeichnen."},{"word":"bewusst","translation":"aware/conscious","pronunciation":"beh-VOOST","example":"Sich bewusst sein."}]}',
'{"title":"Ohne dass — without ... (different subject)","pattern":"ohne dass + V-final clause = without (someone) doing (different subjects — contrast to ohne...zu)","explanation":"Ohne dass + V-final clause = without (someone) doing something (when subject of ohne-clause differs from main clause). Sie handelt, ohne dass er es merkt = She acts without him noticing. Compare: ohne...zu + Infinitiv (same subject). Key rule: different subjects → ohne dass. Same subject → ohne...zu. Also: ohne es zu wissen (without knowing it — same subject). Common in formal description of unconscious or unnoticed processes.","examples":[{"sentence":"Das Gesetz wurde geändert, ohne dass die Öffentlichkeit informiert worden war.","translation":"The law was changed without the public having been informed."},{"sentence":"Er spricht darüber, ohne dass es ihm bewusst wäre.","translation":"He speaks about it without being conscious of it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Widrig'' means?","options":["adverse","hostile","difficult","unfavourable"],"correctAnswer":"adverse"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Cognitive biases influence our perception and decisions without our being aware of it.","options":["Kognitive Verzerrungen beeinflussen unsere Wahrnehmung und Entscheidungen, ohne dass wir uns dessen bewusst sind.","Wir treffen Entscheidungen ohne es zu merken.","Kognitive Verzerrungen sind unbewusst.","Unsere Entscheidungen werden durch unbewusste Faktoren beeinflusst."],"correctAnswer":"Kognitive Verzerrungen beeinflussen unsere Wahrnehmung und Entscheidungen, ohne dass wir uns dessen bewusst sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gesetz wurde geändert, ohne dass die Öffentlichkeit informiert worden ___.","options":["war","wurde","sein würde","worden ist"],"correctAnswer":"war"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He speaks about it without being conscious of it","wordBankItems":["Er","spricht","darüber",",","ohne","dass","es","ihm","bewusst","wäre","."],"correctAnswer":"Er spricht darüber , ohne dass es ihm bewusst wäre ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ohne dass'' is used when the subjects of the two clauses are?","options":["different","the same","both animate","both inanimate"],"correctAnswer":"different"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss society and the individual at B2","Use Gesellschaft und Individuum vocabulary","Talk about social norms and identity"],"explanation":{"intro":"Society and individual vocabulary covers social norms, identity, conformity, and individuality at B2.","culturalNote":"The tension between Gesellschaft (society) and Individuum (individual) is a core theme in German sociology (Simmel, Tönnies — Gemeinschaft vs. Gesellschaft). Key concepts: soziale Normen (social norms), Konformitätsdruck (conformity pressure), Rollenerwartungen (role expectations), Identitätsbildung (identity formation). The postmodern critique of fixed identities (flüssige Identitäten — liquid identities, Bauman) is widely discussed."},"examples":[{"german":"Das Spannungsfeld zwischen individueller Freiheit und gesellschaftlichen Erwartungen prägt das Leben vieler Menschen.","english":"The tension between individual freedom and social expectations shapes the lives of many people."},{"german":"Soziale Normen sind unsichtbar und doch machtvoll — sie steuern Verhalten, ohne explizit ausgesprochen zu werden.","english":"Social norms are invisible and yet powerful — they steer behaviour without being explicitly articulated."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the tension between society and individual, social norms, and identity at B2."}}',
'{"items":[{"word":"das Spannungsfeld","translation":"tension/arena of tension","pronunciation":"dahs SHPAN-oonks-felt","example":"Spannungsfeld."},{"word":"machtvoll","translation":"powerful","pronunciation":"MAKHT-fol","example":"Machtvoll und unsichtbar."},{"word":"steuern","translation":"to steer/control","pronunciation":"SHTOY-ern","example":"Verhalten steuern."},{"word":"unsichtbar","translation":"invisible","pronunciation":"OON-zikht-bar","example":"Unsichtbare Normen."},{"word":"prägen","translation":"to shape/characterise","pronunciation":"PRÄG-en","example":"Das Leben prägen."},{"word":"die Rollenerwartung","translation":"role expectation","pronunciation":"dee ROL-en-er-var-toong","example":"Rollenerwartungen."}]}',
'{"title":"Ohne...zu vs. ohne dass — review at B2","pattern":"ohne + zu + Infinitiv (same subject) vs. ohne dass + V-final (different subjects)","explanation":"B2 review: ohne...zu (same subject): Er handelt, ohne nachzudenken = He acts without thinking. Ohne dass (different subjects): Er handelt, ohne dass sie es weiß = He acts without her knowing. Social norms steer Verhalten, ohne explizit ausgesprochen zu werden = Social norms steer behaviour without being explicitly articulated (ohne...zu with passive infinitive). This passive infinitive construction (ohne + ausgesprochen zu werden) is a hallmark of B2 formal German.","examples":[{"sentence":"Das System funktioniert, ohne dass jemand eingreifen muss.","translation":"The system functions without anyone having to intervene."},{"sentence":"Sie hat reagiert, ohne lange nachzudenken.","translation":"She reacted without thinking long."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Spannungsfeld'' means?","options":["tension/arena of tension","field of tension","zone of conflict","contested space"],"correctAnswer":"tension/arena of tension"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social norms are invisible and yet powerful — they steer behaviour without being explicitly articulated.","options":["Soziale Normen sind unsichtbar und doch machtvoll — sie steuern Verhalten, ohne explizit ausgesprochen zu werden.","Soziale Normen beeinflussen Verhalten unbewusst.","Normen sind machtvoll, obwohl sie unsichtbar sind.","Normen steuern Verhalten, ohne dass man sie sieht."],"correctAnswer":"Soziale Normen sind unsichtbar und doch machtvoll — sie steuern Verhalten, ohne explizit ausgesprochen zu werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das System funktioniert, ohne dass jemand eingreifen ___.","options":["muss","müsste","muss haben","zu müssen"],"correctAnswer":"muss"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She reacted without thinking long","wordBankItems":["Sie","hat","reagiert",",","ohne","lange","nachzudenken","."],"correctAnswer":"Sie hat reagiert , ohne lange nachzudenken ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ohne explizit ausgesprochen zu werden'' contains which grammatical construction?","options":["passive infinitive (Passiv-Infinitiv)","Partizip I","Konjunktiv II","extended participial attribute"],"correctAnswer":"passive infinitive (Passiv-Infinitiv)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

-- Lesson 440: B2 Milestone 2 (xp:200, coins:100)
INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b8',1,'APPROVED','PUBLISHED',
'{"objectives":["Review B2 grammar patterns","Demonstrate mastery of complex structures","Complete B2 milestone 2"],"explanation":{"intro":"Herzlichen Glückwunsch! You have completed 80 lessons at B2 level — a major achievement. This milestone reviews key B2 grammar and vocabulary patterns.","culturalNote":"At B2, you can follow complex arguments and express ideas fluently in German on a wide range of topics. You understand the general message of texts that contain elements of irony, ambiguity, or cultural reference. You can engage in debate, write formal documents, and express nuanced opinions. Willkommen in der oberen B2-Ebene!"},"examples":[{"german":"Ohne die in den letzten Jahren gewonnenen Erkenntnisse wäre es nicht möglich gewesen, dieses Problem zu lösen.","english":"Without the findings gained in recent years, it would not have been possible to solve this problem."},{"german":"Wenngleich die Maßnahmen umstritten sind, lässt sich nicht leugnen, dass sie positive Ergebnisse hervorgebracht haben.","english":"Even though the measures are controversial, it cannot be denied that they have produced positive results."}],"rewards":{"xp":200,"coins":100},"metadata":{"estimatedMinutes":25,"canDo":"I can demonstrate mastery of complex B2 German grammar and vocabulary — Milestone 2 complete!"}}',
'{"items":[{"word":"leugnen","translation":"to deny","pronunciation":"LOYG-nen","example":"Nicht leugnen."},{"word":"hervorgebracht","translation":"produced/brought forth","pronunciation":"her-FOR-geh-brakht","example":"Ergebnisse hervorgebracht."},{"word":"wenngleich","translation":"even though (elevated)","pronunciation":"VEN-glykh","example":"Wenngleich umstritten."},{"word":"gewonnen","translation":"gained/obtained","pronunciation":"geh-VON-en","example":"Gewonnene Erkenntnisse."},{"word":"hervorbringen","translation":"to produce/bring forth","pronunciation":"her-FOR-bring-en","example":"Ergebnisse hervorbringen."},{"word":"sich leugnen lassen","translation":"to be deniable","pronunciation":"zikh LOYG-nen LAS-en","example":"Lässt sich nicht leugnen."}]}',
'{"title":"Sich nicht leugnen lassen — cannot be denied","pattern":"sich nicht leugnen lassen = cannot be denied (sich lassen + Infinitiv passive alternative)","explanation":"Sich lassen + Infinitiv = can be done. Das lässt sich nicht leugnen = That cannot be denied. Das lässt sich nicht ändern = That cannot be changed. This is an active-voice alternative to the passive: Es kann nicht geleugnet werden (passive) = Das lässt sich nicht leugnen (active lassen). In formal B2 writing, the lassen construction is often preferred as cleaner. Also: Das lässt sich feststellen (= can be established), Das lässt sich erklären (= can be explained).","examples":[{"sentence":"Die Vorteile lassen sich nicht leugnen.","translation":"The advantages cannot be denied."},{"sentence":"Das lässt sich einfach nicht rechtfertigen.","translation":"That simply cannot be justified."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Leugnen'' means?","options":["to deny","to lie","to refute","to negate"],"correctAnswer":"to deny"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Even though the measures are controversial, it cannot be denied that they have produced positive results.","options":["Wenngleich die Maßnahmen umstritten sind, lässt sich nicht leugnen, dass sie positive Ergebnisse hervorgebracht haben.","Die Maßnahmen waren umstritten, aber positiv.","Obwohl die Maßnahmen Kritik erhielten, waren sie erfolgreich.","Die positiven Ergebnisse sprechen für sich."],"correctAnswer":"Wenngleich die Maßnahmen umstritten sind, lässt sich nicht leugnen, dass sie positive Ergebnisse hervorgebracht haben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Vorteile lassen sich nicht ___.","options":["leugnen","leugnen können","zu leugnen","geleugnet"],"correctAnswer":"leugnen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: That simply cannot be justified","wordBankItems":["Das","lässt","sich","einfach","nicht","rechtfertigen","."],"correctAnswer":"Das lässt sich einfach nicht rechtfertigen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das lässt sich nicht leugnen'' is the active equivalent of?","options":["Es kann nicht geleugnet werden","Man kann es nicht leugnen","Es ist unleugbar","Niemand leugnet es"],"correctAnswer":"Es kann nicht geleugnet werden"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

